import React, { useState, useEffect, useContext } from 'react';
import { callLLM, callML , getVersion,  health, imageToText } from "./api";

const SubApp = () => {
	const [text, setText] = useState("");
	const [result, setResult] = useState("");
	const [loading, setLoading] = useState(false);

	const runLLM = async () => {
		setLoading(true);
		const output = await callLLM(text);
		// const output = await imageToText(text);
		setResult(output);
		setLoading(false);
	};

	const runML = async () => {
		setLoading(true);
		const features = [5.1, 3.5, 1.4, 0.2];
		const output = await callML(features);
		console.log(output)
		setResult(output);
		setLoading(false);
	};


	useEffect(() => {
		const fetchVersion = async () => {
			try {
				const resultHealth = await health();
				console.log(resultHealth);

				const result = await getVersion([1, 2, 3]);
				console.log(result);
			} catch (error) {
				console.error("API calling error:", error);
			}
		};

		fetchVersion();
	}, []);

	return (

		
		<div style= {{ padding: "2rem", fontFamily: "sans-serif" }}>
		
		<h2>Local ML</h2>
		< button onClick = { runML } disabled = { loading }>
			{ loading? "Running ML...": "Run ML" }
		</button>

		<br />
		
		<h2>Local LLM</h2>
		<div>
		< textarea
			value = { text }
			onChange = {(e) => setText(e.target.value)}
			rows = { 4}
			cols = { 50}
			placeholder = "Type your prompt for LLM..."
				/>
		</div>
		<br />

		< button onClick = { runLLM } disabled = { loading } >
			{ loading? "Running LLM...": "Run LLM" }
		</button>



		< h2 > Result: </h2>
		< pre > { result } </pre>
		</div>
  );
}

export default SubApp;