export const API_BASE_LOCAL = "http://127.0.0.1:8000";

export const callLLM = async (prompt: string): Promise<string> => {
	try {
		// console.log({ prompt })
		const response = await fetch(`${API_BASE_LOCAL}/api/v1/predict_llm`, {
			method: "POST",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify({ text: prompt }),
		});

		if (!response.ok) throw new Error("Network response was not ok");
		const data = await response.json();
		return data.result || "No result";
	} catch (error) {
		console.error("LLM API Error:", error);
		return "Error calling LLM API";
	}
}

